import java.util.ArrayList;
import java.util.List;

/**
 * A document with an id and some text, able to break itself into words.
 *
 * PROVIDED FILE -- this class is complete. Do not edit it.
 */
public class IndexedDocument {

    private final String id;
    private final String text;

    public IndexedDocument(String id, String text) {
        this.id = id;
        this.text = text;
    }

    public String getId() {
        return id;
    }

    public String getText() {
        return text;
    }

    /**
     * The words of this document, lower-cased, with punctuation dropped.
     * "The cat, the hat!" -> [the, cat, the, hat]
     */
    public List<String> words() {
        List<String> found = new ArrayList<>();
        for (String piece : text.toLowerCase().split("[^a-z0-9]+")) {
            if (!piece.isEmpty()) {
                found.add(piece);
            }
        }
        return found;
    }
}

