import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.TreeSet;

public class InvertedIndex {

    private final Map<String, Set<String>> index = new HashMap<>();
    private final Set<String> documentIds = new TreeSet<>();

    public void add(IndexedDocument document) {
        documentIds.add(document.getId());
        for (String word : document.words()) {
            index.computeIfAbsent(word, key -> new TreeSet<>()).add(document.getId());
        }
    }

    public int documentCount() {
        return documentIds.size();
    }

    public int vocabularySize() {
        return index.size();
    }

    public List<String> lookup(String word) {
        Set<String> ids = index.get(word.toLowerCase());
        if (ids == null) {
            return new ArrayList<>();
        }
        return new ArrayList<>(ids);
    }

    public List<String> search(String[] words) {
        if (words.length == 0) {
            return new ArrayList<>();
        }
        Set<String> matches = new TreeSet<>(lookup(words[0]));
        for (int i = 1; i < words.length; i++) {
            matches.retainAll(lookup(words[i]));
        }
        return new ArrayList<>(matches);
    }
}

