public class InvertedIndexTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        InvertedIndex index = new InvertedIndex();
        index.add(new IndexedDocument("d1", "The cat sat on the mat."));
        index.add(new IndexedDocument("d2", "A dog sat down."));
        index.add(new IndexedDocument("d3", "The cat and the dog!"));

        check("document count", 3, index.documentCount());
        check("vocabulary size", 9, index.vocabularySize());
        check("lookup a word in two documents", "[d1, d3]",
              String.valueOf(index.lookup("cat")));
        check("lookup is case-insensitive", "[d1, d3]", String.valueOf(index.lookup("CAT")));
        check("a word repeated in a document lists it once", "[d1, d3]",
              String.valueOf(index.lookup("the")));
        check("lookup a word in a single document", "[d2]", String.valueOf(index.lookup("down")));
        check("lookup an unknown word", "[]", String.valueOf(index.lookup("zebra")));

        check("search for two words", "[d3]",
              String.valueOf(index.search(new String[]{"the", "dog"})));
        check("search for one word", "[d1, d2]",
              String.valueOf(index.search(new String[]{"sat"})));
        check("search with no match", "[]",
              String.valueOf(index.search(new String[]{"cat", "down"})));
        check("search with no words", "[]", String.valueOf(index.search(new String[0])));

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

